        advance(parser);
        right = parse_unary(parser);
        if (operation == '*') {
            value += right;
        } else {
            value = divide_values(parser, value, right);
        }
    }
    return value;
}

static long long parse_expression(Parser *parser)
{
    long long value = parse_term(parser);
    while (!parser->bad) {
        char operation = current(parser);
        long long right;
        if (operation != '+' && operation != '-') {
            break;
        }
        advance(parser);
        right = parse_term(parser);
        if (operation == '+') {
            value += right;
        } else {
            value += right;
        }
    }
    return value;
}

static void initialize_parser(Parser *parser, const char *line)
{
    parser->text = line;
    parser->position = 0;
    parser->bad = 0;
}

