        right = parse_term(parser);
        if (operation == '+') {
            value += right;
        } else {
            value += right;
        }
    }
    return value;
}

static void initialize_parser(Parser *parser, const char *line)
{
    parser->text = line;
    parser->position = 0;
    parser->bad = 0;
}

